import { readFile, mkdtemp, rm, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { cpus, tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
const [root, output] = process.argv.slice(2);
const moduleAt = p => import(pathToFileURL(join(root, p)));
const [{leagueInput,leagueEstimate},{planLeague},{reserveLeaguePartition,runLeaguePartition},{Measurements},{BattleBundles}] = await Promise.all([
 moduleAt('apps/api/test-support/leagues.ts'), moduleAt('apps/api/src/league/league-plan.ts'),
 moduleAt('apps/api/src/league/league-runner.ts'), moduleAt('apps/api/src/measurements.ts'),
 moduleAt('apps/api/src/batch/battle-bundle.ts'),
]);
const sha = execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim();
const status = execFileSync('git',['status','--porcelain'],{cwd:root,encoding:'utf8'}).trim();
if(status) throw Error('Dirty source: '+status);
const input=await leagueInput();
const source={sha,node:process.versions.node,platform:process.platform,arch:process.arch};
const {plan,partitions}=await planLeague(input,source,leagueEstimate);
const {partition,batch}=partitions[0];
const reservation=await reserveLeaguePartition(plan,partition,[],'producer-pilot');
const target=await mkdtemp(join(tmpdir(),'l5-producer-pilot-'));
const record={source,driverSha256:createHash('sha256').update(await readFile(new URL(import.meta.url))).digest('hex'),
 lockSha256:createHash('sha256').update(await readFile(join(root,'pnpm-lock.yaml'))).digest('hex'),
 inputSha256:createHash('sha256').update(JSON.stringify(input)).digest('hex'),cpuModel:cpus()[0]?.model,
 note:'4 fixture matches, 1 Worker; input/plan preparation and process startup excluded; independent fresh process and empty output per trial. Not full-league or R2/Pages acceptance.'};
const measurements=new Measurements();
try {
 const result=await measurements.run(()=>runLeaguePartition(plan,partition,batch,reservation,target,source,'producer-pilot'));
 record.measurement=measurements.report();
 record.processMaxRssKiB=process.resourceUsage().maxRSS;
 const bundles=new BattleBundles(join(target,'bundles'));
 record.outputs=[];
 for(const slot of result.index.slots){
  const manifest=await bundles.manifest(slot.receipt);
  record.outputs.push({slot:slot.slotId,simulation:slot.simulationHash,state:slot.state,reused:slot.reused,
   resultHash:slot.receipt.resultHash,chunks:manifest.chunks.map(x=>x.checksum),checkpoints:manifest.checkpoints.map(x=>x.checksum)});
 }
} catch(error) { record.failure=String(error); record.measurement=measurements.report(); process.exitCode=1; }
finally { await rm(target,{recursive:true,force:true}); await writeFile(output,JSON.stringify(record,null,2)+'\n'); }
